// Pega o array de mensagens do LLM
const mensagens = $json.output.mensagens;

// Garante que é mesmo um array
if (!Array.isArray(mensagens)) {
  return [{ json: { mensagem: mensagens } }];
}

// Retorna 1 item por mensagem
return mensagens.map(texto => ({
  json: { mensagem: texto }
}));

