={{ 
  (() => {
    const key = $('Webhook').item.json.body.data.key || {};
    const jid = key.remoteJid || '';
    const jidAlt = key.remoteJidAlt || '';

    // 1) Preferir sempre o que tiver "@s.whatsapp.net" (número real)
    let chosen = '';
    if (jidAlt && jidAlt.includes('@s.whatsapp.net')) {
      chosen = jidAlt;
    } else if (jid && jid.includes('@s.whatsapp.net')) {
      chosen = jid;
    } else {
      // fallback: o que existir
      chosen = jidAlt || jid || '';
    }

    // 2) Tirar sufixo e possível ":device"
    return chosen
      .replace('@s.whatsapp.net', '')
      .split(':')[0];
  })()
}}
